#include <stdio.h>
int main(void) {
    FILE *w = fopen("nl.txt", "w");   /* 文本模式写：\n 会被转成 \r\n 落盘 */
    fputs("AB\nCD", w);
    fclose(w);
    FILE *rb = fopen("nl.txt", "rb"); /* 二进制读：原样 6 字节 */
    unsigned char b[16]; size_t nb = fread(b, 1, 16, rb); fclose(rb);
    FILE *rt = fopen("nl.txt", "r");  /* 文本读：\r\n 被还原成 \n，得 5 字节 */
    unsigned char t[16]; size_t nt = fread(t, 1, 16, rt); fclose(rt);
    printf("binary read: %zu bytes -> ", nb);
    for (size_t i = 0; i < nb; i++) printf("%02X ", b[i]);
    printf("\n");
    printf("text read:   %zu bytes -> ", nt);
    for (size_t i = 0; i < nt; i++) printf("%02X ", t[i]);
    printf("\n");
    return 0;
}
